#include <iostream>
#include <vector>
using namespace std;

int main() {
    vector<vector<long long>> dp(40, vector<long long>(40, 0));
    int N, H;
    cin >> N >> H;
    for (int i = 0; i < 40; ++i) {
        dp[0][i] = 1;
    }
    for (int i = 1; i < 40; ++i) {
        for (int j = 1; j < 40; ++j) {
            for (int k = 0; k < i; ++k) {
                dp[i][j] += dp[k][j - 1] * dp[i - 1 - k][j - 1];
            }
        }
    }
    long long res = dp[N][N] - ((H > 0) ? dp[N][H - 1] : 0);
    cout << res << endl;
    return 0;
}
